[{"order":1,"type":"heading","text":"API Testing Tutorial: RestAssured, Postman, and Playwright API"},{"order":2,"type":"paragraph","text":"API testing is a critical component of modern software engineering. It ensures that backend services are reliable, performant, and secure. This tutorial covers three of the most popular tools used by automation engineers today: Postman for exploratory and collection-based testing, RestAssured for Java-based automated test suites, and Playwright API for modern end-to-end testing scenarios."},{"order":3,"type":"subheading","text":"1. API Testing with Postman"},{"order":4,"type":"paragraph","text":"Postman is an industry-standard API client that allows developers and testers to execute manual requests, build automated collections, and integrate testing into CI/CD pipelines using Newman."},{"order":5,"type":"bullet_point","text":"Create a new GET request in Postman targeting https://jsonplaceholder.typicode.com/posts/1."},{"order":6,"type":"bullet_point","text":"Navigate to the 'Tests' tab to write assertion scripts using JavaScript and the pm object."},{"order":7,"type":"code","text":"pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Response has correct userId", function () {
    var jsonData = pm.response.json();
    pm.expect(jsonData.userId).to.eql(1);
});"},{"order":8,"type":"subheading","text":"2. API Testing with RestAssured (Java)"},{"order":9,"type":"paragraph","text":"RestAssured is a powerful Java Domain Specific Language (DSL) that simplifies the testing of RESTful services. It integrates seamlessly with testing frameworks like TestNG or JUnit and build tools like Maven or Gradle."},{"order":10,"type":"bullet_point","text":"Add the RestAssured dependency to your Maven pom.xml file."},{"order":11,"type":"bullet_point","text":"Write a test using Given-When-Then syntax to validate endpoints."},{"order":12,"type":"code","text":"import io.restassured.RestAssured;
import org.testng.annotations.Test;
import static io.restassured.RestAssured.*;
import static org.hamcrest.Matchers.*;

public class ApiTest {
    @Test
    public void testGetPost() {
        given()
            .baseUri("https://jsonplaceholder.typicode.com")
        .when()
            .get("/posts/1")
        .then()
            .statusCode(200)
            .body("id", equalTo(1))
            .body("title", notNullValue());
    }
}"},{"order":13,"type":"subheading","text":"3. API Testing with Playwright API"},{"order":14,"type":"paragraph","text":"Playwright is widely known for browser automation, but it also provides a robust APIRequestContext class. This allows you to perform API testing and automate UI-to-API scenarios within the same test runner framework."},{"order":15,"type":"bullet_point","text":"Initialize the request context using Playwright in JavaScript or TypeScript."},{"order":16,"type":"bullet_point","text":"Execute HTTP methods and assert on responses."},{"order":17,"type":"code","text":"const { test, expect } = require('@playwright/test');

test('should fetch post details via API', async ({ request }) => {
  const response = await request.get('https://jsonplaceholder.typicode.com/posts/1');
  expect(response.status()).toBe(200);

  const responseBody = await response.json();
  expect(responseBody.id).toBe(1);
  expect(responseBody).toHaveProperty('title');
});"},{"order":18,"type":"subheading","text":"Conclusion"},{"order":19,"type":"paragraph","text":"Choosing the right tool depends entirely on your technology stack and project requirements. Postman excels at rapid prototyping and manual validation. RestAssured is the gold standard for Java-centric backend testing teams. Playwright API offers an exceptional unified solution for teams already leveraging Playwright for frontend UI automation."}]
